mapper.select:
SELECT SERVICE_ID, ATCHFILEPATH_NM, ATCHFILE_NM, SEQ, ATCHSVRFILE_NM, GUBUN, INS_USER, TO_CHAR(INS_DATE, 'YYYY-MM-DD HH24:MI:SS') AS INS_DATE, UPD_USER, TO_CHAR(UPD_DATE, 'YYYY-MM-DD HH24:MI:SS') AS UPD_DATE FROM TR_ATTACH_FILE WHERE SERVICE_ID = #{SERVICE_ID}
AND ( GUBUN = #{GUBUN}
OR GUBUN = #{GUBUN2}
)
AND ATCHSVRFILE_NM LIKE #{ATCHSVRFILE_NM} || '%'
ORDER BY TO_NUMBER(SEQ)

mapper.delete:
DELETE FROM TR_ATTACH_FILE
 WHERE SERVICE_ID = #{SERVICE_ID}

   AND GUBUN = #{GUBUN}


   AND SEQ = #{SEQ}


   AND ATCHSVRFILE_NM = #{ATCHSVRFILE_NM}
